def page(p):
    url=BASE+'services/products/'+p['slug']+'.html'
    image=BASE+p['img'].replace('../../','')
    graph={'@context':'https://schema.org','@graph':[{'@type':['Organization','LocalBusiness'],'@id':BASE+'#organization','name':'شرکت پیشرو تجهیز فرتاک','url':BASE,'logo':BASE+'assets/images/ptf-logo.png'},{'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'خانه','item':BASE},{'@type':'ListItem','position':2,'name':'محصولات','item':BASE+'services/products/'},{'@type':'ListItem','position':3,'name':p['fa'],'item':url}]},{'@type':'Product','name':p['fa'],'alternateName':p['en'],'category':p['cat'],'description':p['desc'],'image':image,'brand':{'@type':'Brand','name':'پیشرو تجهیز فرتاک'},'offers':{'@type':'AggregateOffer','priceCurrency':'IRR','availability':'https://schema.org/InStock','itemCondition':'https://schema.org/NewCondition','url':url},'mainEntityOfPage':{'@type':'WebPage','@id':url}},{'@type':'FAQPage','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a in p['faq']]}]}
    sections=''.join(f'<h2>{escape(h)}</h2><p>{escape(txt)}</p>' for h,txt in p['sections'])
    content=f'''<!doctype html><html lang="fa" dir="rtl"><head><link rel="icon" type="image/png" sizes="32x32" href="../../assets/images/favicon/favicon-32.png"><link rel="icon" type="image/png" sizes="96x96" href="../../assets/images/favicon/favicon-96.png"><link rel="icon" type="image/png" sizes="192x192" href="../../assets/images/favicon/favicon-192.png"><link rel="apple-touch-icon" sizes="180x180" href="../../assets/images/favicon/apple-touch-icon.png"><link rel="shortcut icon" href="../../favicon.ico"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{escape(p['title'][:68])}</title><meta name="description" content="{escape(p['desc'][:165])}"><meta name="robots" content="index, follow, max-image-preview:large, max-snippet:-1"><link rel="canonical" href="{url}"><link rel="alternate" hreflang="fa-IR" href="{url}"><link rel="alternate" hreflang="x-default" href="{url}"><meta property="og:locale" content="fa_IR"><meta property="og:site_name" content="پیشرو تجهیز فرتاک"><meta property="og:title" content="{escape(p['title'])}"><meta property="og:description" content="{escape(p['desc'][:165])}"><meta property="og:type" content="product"><meta property="og:url" content="{url}"><meta property="og:image" content="{image}"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{escape(p['title'][:68])}"><meta name="twitter:description" content="{escape(p['desc'][:165])}"><meta name="twitter:image" content="{image}"><link rel="stylesheet" href="../../assets/css/style.css"><script type="application/ld+json">{json.dumps(graph,ensure_ascii=False,separators=(',',':'))}</script>{CSS}</head><body><header class="site-header scrolled"><div class="container nav-wrap"><a class="brand" href="../../"><img width="54" height="54" loading="lazy" src="../../assets/images/ptf-logo.png" alt="لوگو شرکت پیشرو تجهیز فرتاک"><span><b>پیشرو تجهیز فرتاک</b><small>Pishro Tajhiz Fartak</small></span></a><nav class="main-nav" id="mainNav"><a href="../../">خانه</a><a href="../../services/" class="active">خدمات</a><a href="../../services/products/">محصولات</a><a href="../../knowledge-center/">مرکز دانش</a><a href="../../rfq/">استعلام</a></nav><a class="header-call" href="tel:02146087679">021-46087679</a></div></header><main class="ptf-product-main"><div class="container"><div class="ptf-breadcrumb"><a href="../../">خانه</a> › <a href="./">محصولات</a> › {escape(p['fa'])}</div><section class="ptf-product-hero"><div class="ptf-hero-grid"><div><h1>{escape(p['title'])}</h1><p>{escape(p['desc'])}</p><span class="ptf-chip">{escape(p['cat'])}</span><span class="ptf-chip">راهنمای جامع کاربر محصول</span><span class="ptf-chip">تصویر کم‌حجم تک‌محصولی</span></div><div class="ptf-hero-card"><img src="{p['img']}" alt="{escape(p['fa'])}" width="990" height="540" loading="eager"></div></div></section><div class="ptf-layout"><article class="ptf-article"><h2>این صفحه برای چه کسی نوشته شده است؟</h2><p>این راهنما فقط برای ثبت سفارش نیست؛ برای کارشناس خرید، مهندس پروژه، تیم نصب، واحد بهره‌برداری، کنترل کیفیت و بازرسی نوشته شده است. هدف این است که قبل از ارسال RFQ، معیارهای واقعی انتخاب {escape(p['fa'])} روشن باشد و پیشنهادهای فروشندگان قابل مقایسه شوند.</p>{sections}<section class="ptf-box ptf-brand-box"><h2>برندها و سازندگان قابل بررسی</h2><p>{escape(p['brand_note'])}</p>{list_html(p['brands'])}</section><h2>استانداردهای مهم</h2>{list_html(p['standards'])}<h2>داده‌های لازم برای RFQ</h2>{list_html(p['rfq'])}<h2>خطاهای رایج خرید</h2>{list_html(p['pitfalls'])}<table class="ptf-spec"><tr><th>نام محصول</th><td>{escape(p['fa'])} / {escape(p['en'])}</td></tr><tr><th>دسته</th><td>{escape(p['cat'])}</td></tr><tr><th>مدارک پایه</th><td>Datasheet، MTC/Test Report، گواهی سازنده، Packing List و مدارک بازرسی طبق پروژه</td></tr></table><div class="ptf-cta"><h2>ثبت RFQ برای {escape(p['fa'])}</h2><p>داده‌های موجود را ارسال کنید تا موارد ناقص قبل از قیمت‌گیری مشخص شود.</p><a class="ptf-btn" href="../../rfq/?product={p['slug']}">ثبت RFQ این محصول ←</a></div><h2>مطالب مرتبط</h2><div class="ptf-related">{''.join(f'<a href="{href}">{escape(label)}</a>' for label,href in p['links'])}<a href="{p['service']}">صفحه خدمات مرتبط</a><a href="./">هاب محصولات</a></div><h2>پرسش‌های متداول</h2>{''.join(f'<div class="ptf-faq"><b>{escape(q)}</b><p>{escape(a)}</p></div>' for q,a in p['faq'])}<p>برای جمع‌بندی، خرید مطمئن {escape(p['fa'])} زمانی انجام می‌شود که استاندارد، متریال، برندهای مجاز، مدارک، روش تست و شرایط نصب قبل از مذاکره قیمت مشخص شده باشد. اگر این موارد مبهم بماند، کمترین قیمت می‌تواند به پرریسک‌ترین انتخاب پروژه تبدیل شود.</p></article><aside class="ptf-side"><h3>دسترسی سریع</h3><a href="../../rfq/?product={p['slug']}">ثبت RFQ</a><a href="./">همه محصولات</a><a href="{p['service']}">خدمات مرتبط</a><a href="../../quality/">تضمین کیفیت</a></aside></div></div></main>{footer()}<script src="../../assets/js/main.js"></script><script src="../../assets/js/ptf-metrics.js" defer></script><div class="ptf-mobile-product-cta"><span>{escape(p['fa'])}</span><a href="../../rfq/?product={p['slug']}">ثبت RFQ سریع</a></div></body></html>'''
    extra=[f'در ارزیابی نهایی {p["fa"]}، بهتر است پیشنهادها در یک جدول Technical Bid Evaluation کنار هم قرار بگیرند تا انحراف‌ها، مدارک ناقص و تفاوت برندها قبل از صدور سفارش مشخص شود.', f'برای {p["fa"]}، زمان تحویل واقعی شامل آماده‌سازی مدارک، بازرسی، بسته‌بندی، حمل و تأیید کارفرماست؛ بنابراین فقط موجودی اولیه یا قیمت واحد نباید معیار تصمیم باشد.']
    if words(content)<1700:
        content=content.replace('</article>',''.join(f'<p>{escape(x)}</p>' for x in extra)+'</article>')
    return content

for p in PRODUCTS:
    (OUT/f"{p['slug']}.html").write_text(page(p),encoding='utf-8')
    print(p['slug'], words((OUT/f"{p['slug']}.html").read_text(encoding='utf-8')))
